package com.example.starter.damage.api;

/** 残损案状态机：到港登记→检验→估价→修理批复→复检→放行/全损。 */
public enum CaseStatus {

    /** 已到港登记，尚未检验。 */
    REGISTERED,
    /** 已完成检验，残损清单已登记。 */
    SURVEYED,
    /** 已估价，估价结论为修理。 */
    ESTIMATED,
    /** 修理批复已生效（7 个自然日有效期内）。 */
    REPAIR_APPROVED,
    /** 修理已完工，等待复检。 */
    REPAIR_COMPLETED,
    /** 复检不合格，待返修（仅允许一次）。 */
    REWORK_REQUIRED,
    /** 复检合格已放行，案件结案（终态）。 */
    RELEASED,
    /** 判定全损，案件结案（终态）。 */
    TOTAL_LOSS
}

package com.example.starter.damage.api;

/** 残损/修理责任方。 */
public enum Responsibility {

    /** 箱东责任。 */
    OWNER,
    /** 码头责任。 */
    TERMINAL
}

package com.example.starter.damage.api;

/** 估价结论：修理与全损互斥，判定唯一。 */
public enum EstimateDecision {

    /** 修理（最大单项修理费 ≤ 箱值 30%，恰 30% 亦修理）。 */
    REPAIR,
    /** 全损（最大单项修理费 > 箱值 30%）。 */
    TOTAL_LOSS
}

package com.example.starter.damage.api;

/** 业务异常：携带 HTTP 状态码与稳定错误码，由全局处理器转换为响应体。 */
public class ApiException extends RuntimeException {

    private final int status;
    private final String code;

    public ApiException(int status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public int getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }

    public static ApiException notFound(String message) {
        return new ApiException(404, "NOT_FOUND", message);
    }

    public static ApiException conflict(String code, String message) {
        return new ApiException(409, code, message);
    }

    public static ApiException unprocessable(String code, String message) {
        return new ApiException(422, code, message);
    }

    public static ApiException badRequest(String code, String message) {
        return new ApiException(400, code, message);
    }
}

package com.example.starter.damage.api;

import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.LinkedHashMap;
import java.util.Map;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/** 统一错误响应：{ code, message, timestampUtc }。 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<Map<String, Object>> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.getStatus()).body(body(ex.getCode(), ex.getMessage()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Map<String, Object>> handleValidation(MethodArgumentNotValidException ex) {
        String message = ex.getBindingResult().getFieldErrors().stream()
                .map(e -> e.getField() + " " + e.getDefaultMessage())
                .findFirst()
                .orElse("请求参数校验失败");
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(body("VALIDATION_FAILED", message));
    }

    private Map<String, Object> body(String code, String message) {
        Map<String, Object> map = new LinkedHashMap<>();
        map.put("code", code);
        map.put("message", message);
        map.put("timestampUtc", OffsetDateTime.now(ZoneOffset.UTC).toString());
        return map;
    }
}

