                "RP-POST", "角柱火焰矫正", new BigDecimal("300.00"), 1,
                new BigDecimal(amount), 0L);
    }

    @Test
    @DisplayName("单项修理费恰为箱值 30%：判定修理")
    void exactlyThirtyPercentIsRepair() {
