        RegisterResponse reg = register("REQ-REG-1", "CSQU3001001", "1000.00", d1);
        String caseNo = reg.caseNo();

        // 单项 RP-POST 300.00，恰为箱值 1000 的 30% → 修理。
        CaseResponse surveyed = survey("REQ-SUR-1", caseNo, d1 + 3_600_000L,
